// Build signed app bundles (.skb) from app directories, using the author key. The browser
// never signs; it only verifies what this produces.
//
//   node scripts/build-app-bundle.mjs                     every app under assembly/
//   node scripts/build-app-bundle.mjs assembly/jam-app    just jam
//
// An app directory is one with an `app.json` (read by scripts/app-source.mjs). Output:
// bundle/<label>.skb (§12.4).
//
// A `"boot": true` app (assembly/shell-app) is loaded by the page at boot, by pin. The page
// is served from browser/, so it also gets browser/<label>-bundle.js (gitignored): the
// bundle as base64 plus the author and app the page pins it by.

import { existsSync, readdirSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

import { loadCrypto } from "seedkernel-wasm";
import { authorBundle, guestOpFraming } from "seedkernel-wasm/bundle-author";
import { readAppSource } from "./app-source.mjs";
import { authorKeys, nextVersion, saveVersion } from "./author.mjs";
import { toHex } from "../browser/app-api.js";

const __dirname = dirname(fileURLToPath(import.meta.url));
const root = join(__dirname, "..");
const assembly = join(root, "assembly");

const named = process.argv.slice(2).map((dir) => resolve(root, dir));
const appDirs = named.length > 0 ? named
  : readdirSync(assembly).map((name) => join(assembly, name)).filter((dir) => existsSync(join(dir, "app.json")));

/** The generated JS module for a boot bundle. */
function bootModule(label, blob, author) {
  if (!/^[a-z][a-z0-9_]*$/.test(label)) throw new Error(`a boot bundle's label names its exports, so "${label}" must be [a-z][a-z0-9_]*`);
  return `// GENERATED by scripts/build-app-bundle.mjs — DO NOT EDIT.
// The ${label} boot bundle (assembly/${label}-app), loaded at boot by its pin, signed by
//   ${toHex(author)}
// under the hybrid suite 0x02 (Ed25519 + ML-DSA-65), the same author as every app bundle.
const B64 = "${Buffer.from(blob).toString("base64")}";
let decoded = null;
/** The boot bundle as raw bytes. A fresh copy per call. */
export function ${label}BundleBytes() {
  decoded ??= Uint8Array.from(atob(B64), (c) => c.charCodeAt(0));
  return decoded.slice();
}
/** The author this bundle is signed by (hex), which \`admit\` pins the boot load to. */
export const ${label.toUpperCase()}_AUTHOR_HEX = "${toHex(author)}";
/** The app its manifest declares, which \`admit\` checks beside the author. */
export const ${label.toUpperCase()}_APP = ${JSON.stringify(label)};
`;
}

const sodium = await loadCrypto();

// Key and version counts live in scripts/author.mjs. The shell doesn't gate installs on
// versions (it uses consent, §12.4), but we keep a true count rather than restart at 1.
const keys = authorKeys(sodium);
mkdirSync(join(root, "bundle"), { recursive: true });

/** Label → source dir, so two apps with the same label don't overwrite each other. */
const built = new Map();
for (const dir of appDirs) {
  const source = await readAppSource(dir, guestOpFraming);
  if (built.has(source.app))
    throw new Error(`${dir} and ${built.get(source.app)} are both the app "${source.app}": give one another label in its app.json`);
  built.set(source.app, dir);
  const version = nextVersion(source.app);
  const { blob, manifest, author } = authorBundle(sodium, keys, { ...source, version });
  saveVersion(source.app, version);
  const out = `bundle/${source.app}.skb`;
  writeFileSync(join(root, out), blob);
  if (source.boot) writeFileSync(join(root, "browser", `${source.app}-bundle.js`), bootModule(source.app, blob, author));

  // The author id is the hash of the whole key set (§12.4), not just the Ed25519 key, since
  // manifests are signed by both halves.
  if (built.size === 1) console.log(`  author ${toHex(author)} (hybrid 0x02)`);
  const { name, version: label } = manifest.guest.config.shell;
  console.log(`  wrote ${out} (app ${manifest.app} v${manifest.version}, ${[name, label].filter(Boolean).join(" ")})`);
}
